#include <stdio.h>
#include <stdlib.h>
struct Pair { int key; int value; };

int main(void) {
    struct Pair books[] = {{2, 3}, {5, 1}};
    int size = 2;
    for (int i = 0; i < size; i++) {
        if (books[i].key == 2) books[i].value = 6;
    }
    for (int i = 0; i < size; i++) {
        if (books[i].key == 2) {
            printf("%d\n", books[i].value);
            break;
        }
    }
    printf("%d\n", size);
    return 0;
}

#include <iostream>
#include <map>

int main() {
    std::map<int, int> books = {{2, 3}, {5, 1}};
    books[2] = 6;
    auto found = books.find(2);
    if (found != books.end()) std::cout << found->second << '\n';
    std::cout << books.size() << '\n';
    return 0;
}

